use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < K , V > SsoHashMap < K , V > { # [doc = " Creates an empty `SsoHashMap`."] # [inline] pub fn new () -> Self { SsoHashMap :: Array (ArrayVec :: new ()) } # [doc = " Creates an empty `SsoHashMap` with the specified capacity."] pub fn with_capacity (cap : usize) -> Self { if cap <= SSO_ARRAY_SIZE { Self :: new () } else { SsoHashMap :: Map (FxHashMap :: with_capacity_and_hasher (cap , Default :: default ())) } } # [doc = " Clears the map, removing all key-value pairs. Keeps the allocated memory"] # [doc = " for reuse."] pub fn clear (& mut self) { match self { SsoHashMap :: Array (array) => array . clear () , SsoHashMap :: Map (map) => map . clear () , } } # [doc = " Returns the number of elements the map can hold without reallocating."] pub fn capacity (& self) -> usize { match self { SsoHashMap :: Array (_) => SSO_ARRAY_SIZE , SsoHashMap :: Map (map) => map . capacity () , } } # [doc = " Returns the number of elements in the map."] pub fn len (& self) -> usize { match self { SsoHashMap :: Array (array) => array . len () , SsoHashMap :: Map (map) => map . len () , } } # [doc = " Returns `true` if the map contains no elements."] pub fn is_empty (& self) -> bool { match self { SsoHashMap :: Array (array) => array . is_empty () , SsoHashMap :: Map (map) => map . is_empty () , } } # [doc = " An iterator visiting all key-value pairs in arbitrary order."] # [doc = " The iterator element type is `(&'a K, &'a V)`."] # [inline] pub fn iter (& self) -> < & Self as IntoIterator > :: IntoIter { self . into_iter () } # [doc = " An iterator visiting all key-value pairs in arbitrary order,"] # [doc = " with mutable references to the values."] # [doc = " The iterator element type is `(&'a K, &'a mut V)`."] # [inline] pub fn iter_mut (& mut self) -> impl Iterator < Item = (& '_ K , & '_ mut V) > { self . into_iter () } # [doc = " An iterator visiting all keys in arbitrary order."] # [doc = " The iterator element type is `&'a K`."] pub fn keys (& self) -> impl Iterator < Item = & '_ K > { match self { SsoHashMap :: Array (array) => Either :: Left (array . iter () . map (| (k , _v) | k)) , SsoHashMap :: Map (map) => Either :: Right (map . keys ()) , } } # [doc = " An iterator visiting all values in arbitrary order."] # [doc = " The iterator element type is `&'a V`."] pub fn values (& self) -> impl Iterator < Item = & '_ V > { match self { SsoHashMap :: Array (array) => Either :: Left (array . iter () . map (| (_k , v) | v)) , SsoHashMap :: Map (map) => Either :: Right (map . values ()) , } } # [doc = " An iterator visiting all values mutably in arbitrary order."] # [doc = " The iterator element type is `&'a mut V`."] pub fn values_mut (& mut self) -> impl Iterator < Item = & '_ mut V > { match self { SsoHashMap :: Array (array) => Either :: Left (array . iter_mut () . map (| (_k , v) | v)) , SsoHashMap :: Map (map) => Either :: Right (map . values_mut ()) , } } # [doc = " Clears the map, returning all key-value pairs as an iterator. Keeps the"] # [doc = " allocated memory for reuse."] pub fn drain (& mut self) -> impl Iterator < Item = (K , V) > { match self { SsoHashMap :: Array (array) => Either :: Left (array . drain (..)) , SsoHashMap :: Map (map) => Either :: Right (map . drain ()) , } } }